```apex
public with sharing class ContactDomainService {

    /**
     * Groups the Contacts for the given Accounts by the domain part of the
     * contact's email address (lower-cased). Contacts without a usable email
     * are excluded. A null or empty set of account ids yields an empty map.
     *
     * Record-level sharing rules for the running user are respected.
     *
     * @param accountIds Set of Account ids to look up Contacts for.
     * @return Map of lower-cased email domain to the list of Contacts for it.
     *         Each Contact has Id, Email and AccountId populated.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ];

        for (Contact contact : contacts) {
            String domain = extractEmailDomain(contact.Email);
            if (domain == null) {
                continue;
            }

            List<Contact> contactGroup = contactsByDomain.get(domain);
            if (contactGroup == null) {
                contactGroup = new List<Contact>();
                contactsByDomain.put(domain, contactGroup);
            }
            contactGroup.add(contact);
        }

        return contactsByDomain;
    }

    /**
     * Returns the lower-cased domain portion of an email address (the text
     * after the last '@'), or null when the value is null or has no domain.
     *
     * @param email Raw email value.
     * @return Lower-cased domain, or null when no domain can be determined.
     */
    private static String extractEmailDomain(String email) {
        if (email == null) {
            return null;
        }

        Integer atPosition = email.lastIndexOf('@');
        if (atPosition < 0 || atPosition >= email.length() - 1) {
            return null;
        }

        return email.substring(atPosition + 1).toLowerCase();
    }
}
