```apex
public with sharing class ContactLookupAction {

    /**
     * Finds existing Contacts by email address for a batch of Flow interviews.
     *
     * <p>Exactly one {@link Result} is returned for every {@link Request}, in the
     * same order as the input. Matching is case-insensitive and ignores leading
     * and trailing spaces in the supplied email. When more than one Contact has
     * the same email, the one with the earliest CreatedDate is returned. A blank
     * or null email, or an email that no Contact has, yields found = false and a
     * null contactId. The whole batch is served by a single SOQL query and the
     * running user's sharing rules are enforced.</p>
     *
     * @param requests batch of email lookups (up to 200)
     * @return one Result per Request, in input order
     */
    @InvocableMethod(label = 'Find Contact by Email'
        description = 'Finds an existing Contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.size() == 0) {
            return results;
        }

        // Normalize each request. Build a case-variant set of emails for the
        // single SOQL query and remember which normalized key each request uses.
        // SOQL does not support LOWER()/UPPER() in the WHERE clause, so we query
        // the original, lower-cased and upper-cased forms and then compare
        // case-insensitively in Apex.
        Map<Integer, String> requestToKey = new Map<Integer, String>();
        Set<String> querySet = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String raw = (req != null) ? req.email : null;
            if (String.isBlank(raw)) {
                continue; // blank/null email -> found = false, contactId = null
            }
            String trimmed = raw.trim();
            String key = trimmed.toLowerCase();
            requestToKey.put(i, key);
            querySet.add(trimmed);
            querySet.add(key);
            querySet.add(key.toUpperCase());
        }

        // One SOQL query resolves every email to the earliest-created Contact.
        // Ordering ascending by CreatedDate means the first row seen for an email
        // is the earliest Contact, which we keep via first-wins semantics.
        Map<String, Id> keyToContactId = new Map<String, Id>();
        if (querySet.size() > 0) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :querySet
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String cKey = (c.Email != null) ? c.Email.toLowerCase() : null;
                if (cKey != null && !keyToContactId.containsKey(cKey)) {
                    keyToContactId.put(cKey, c.Id);
                }
            }
        }

        // Produce one Result per Request, preserving the original order.
        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String key = requestToKey.get(i);
            r.found = (key != null && keyToContactId.containsKey(key));
            r.contactId = r.found ? keyToContactId.get(key) : null;
            results.add(r);
        }

        return results;
    }

    /** Input for a single email lookup. */
    public class Request {
        @InvocableVariable(label = 'Email' required = true)
        public String email;
    }

    /** Output for a single email lookup. */
    public class Result {
        @InvocableVariable(label = 'Contact ID')
        public Id contactId;

        @InvocableVariable(label = 'Found')
        public Boolean found;
    }
}
