public class OrderPayloadParser {

    /** Custom exception raised for any invalid order payload. */
    public class PayloadException extends Exception {}

    /** A single order line item. */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /** A parsed sales order. */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    /**
     * Parses an order payload JSON string into an Order.
     * Throws PayloadException for any malformed or incomplete payload.
     */
    public static Order parse(String body) {
        if (body == null || body.trim().isEmpty()) {
            throw new PayloadException('Payload body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (JSONException e) {
            throw new PayloadException('Payload is not valid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }
        Map<String, Object> json = (Map<String, Object>) parsed;

        Order order = new Order();
        order.lines = new List<Line>();

        // number (required)
        String number = asString(json.get('number'));
        if (number == null || number.trim().isEmpty()) {
            throw new PayloadException('Payload is missing the required "number" field.');
        }
        order.orderNumber = number;

        // date (optional, ISO yyyy-MM-dd)
        String dateText = asString(json.get('date'));
        if (dateText != null && !dateText.trim().isEmpty()) {
            order.orderDate = parseDate(dateText.trim());
        }

        // currency (optional)
        order.currencyCode = asString(json.get('currency'));

        // customer.email (optional)
        Object customer = json.get('customer');
        if (customer instanceof Map<String, Object>) {
            order.customerEmail = asString(((Map<String, Object>) customer).get('email'));
        }

        // lines (optional)
        Decimal total = 0;
        Object linesNode = json.get('lines');
        if (linesNode instanceof List<Object>) {
            for (Object lineNode : (List<Object>) linesNode) {
                Line line = parseLine(lineNode);
                order.lines.add(line);
                total += line.lineTotal;
            }
        }
        order.total = total;

        return order;
    }

    private static Line parseLine(Object lineNode) {
        if (!(lineNode instanceof Map<String, Object>)) {
            throw new PayloadException('Each order line must be a JSON object.');
        }
        Map<String, Object> node = (Map<String, Object>) lineNode;
        Line line = new Line();

        String sku = asString(node.get('sku'));
        if (sku == null || sku.trim().isEmpty()) {
            throw new PayloadException('Order line is missing the required "sku" field.');
        }
        line.sku = sku;

        Integer quantity = asInteger(node.get('quantity'));
        if (quantity == null || quantity <= 0) {
            throw new PayloadException('Order line "quantity" must be a positive number.');
        }
        line.quantity = quantity;

        Decimal unitPrice = asDecimal(node.get('unitPrice'));
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Order line "unitPrice" must be a non-negative number.');
        }
        line.unitPrice = unitPrice;

        Decimal discount = asDecimal(node.get('discount'));
        if (discount == null) {
            discount = 0;
        }
        line.discount = discount;

        Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
        line.lineTotal = rawTotal.setScale(2, RoundingMode.HALF_UP);

        return line;
    }

