        Decimal total = order.total;
        if (total == null) {
            total = 0;
        }
        return '{'
            + '"number":' + JSON.serialize(order.orderNumber) + ','
            + '"status":"RECEIVED",'
            + '"lineCount":' + lineCount + ','
            + '"total":' + total
            + '}';
