        return value == null ? null : value.toString();
    }

    private static Integer asInteger(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Decimal) {
            return ((Decimal) value).intValue();
        }
        if (value instanceof Long) {
            return ((Long) value).intValue();
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf((String) value).intValue();
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Decimal asDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return (Decimal) (Integer) value;
        }
        if (value instanceof Long) {
            return (Decimal) (Long) value;
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf((String) value);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Date parseDate(String dateText) {
        try {
            List<String> parts = dateText.split('-');
            if (parts.size() == 3) {
                return Date.newInstance(
                    Integer.valueOf(parts[0]),
                    Integer.valueOf(parts[1]),
                    Integer.valueOf(parts[2])
                );
            }
        } catch (Exception e) {
            // Malformed date: leave orderDate null (not flagged as an error per spec).
        }
        return null;
    }
