    /* Business logic                                                      */
    /* ------------------------------------------------------------------ */

    /**
     * Returns the ACTIVE values of a picklist or multi-select picklist field,
     * in the order they are defined on the field. Inactive values are omitted.
     *
     * @param objectApiName API name of the object (standard or custom, any case)
     * @param fieldApiName  API name of the picklist field (any case)
     * @return list of active {@link Option} values in field-definition order
     * @throws PicklistServiceException if a name is null/blank, the object or
     *                                  field does not exist, or the field is not
     *                                  a picklist / multi-select picklist
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'PicklistService: both the object and field API names are required.'
            );
        }

        final String objectKey = objectApiName.trim().toLowerCase();
        final String fieldKey = fieldApiName.trim().toLowerCase();

        // Resolve the SObject (case-insensitive; standard or custom).
        Schema.DescribeSObjectResult sobjectDesc = null;
        for (Schema.DescribeSObjectResult obj : Schema.getGlobalDescribe().values()) {
            if (obj.getApiName().toLowerCase() == objectKey) {
                sobjectDesc = obj;
                break;
            }
        }
        if (sobjectDesc == null) {
            throw new PicklistServiceException(
                'PicklistService: object \'' + objectApiName + '\' does not exist.'
            );
        }

        // Resolve the field (case-insensitive).
        Schema.DescribeFieldResult fieldDesc = null;
        for (Schema.DescribeFieldResult f : sobjectDesc.fields) {
            if (f.getName().toLowerCase() == fieldKey) {
                fieldDesc = f;
                break;
            }
        }
        if (fieldDesc == null) {
            throw new PicklistServiceException(
                'PicklistService: field \'' + fieldApiName
                + '\' does not exist on object \'' + objectApiName + '\'.'
            );
        }

        // The field must be a picklist or a multi-select picklist.
        final Schema.DisplayType fieldType = fieldDesc.getType();
        if (fieldType != Schema.DisplayType.PICKLIST
                && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'PicklistService: field \'' + objectApiName + '.' + fieldApiName
                + '\' is not a picklist or multi-select picklist.'
            );
        }

        // Collect the active values, preserving the field's definition order.
        final String defaultValue = fieldDesc.getDefaultValue();
        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDesc.getPicklistValues()) {
            if (entry.isActive()) {
                final Boolean isDefault =
                    (defaultValue != null && defaultValue.equals(entry.getValue()));
                options.add(new Option(entry.getValue(), entry.getLabel(), isDefault));
            }
        }
        return options;
    }
