public class ShipmentEventHandler {

    /**
     * Marks matching FB_Sales_Order__c records as shipped based on the incoming
     * shipment events. Runs a single SOQL query and a single DML statement per
     * call regardless of the number of events.
     *
     * - Tracking number and carrier are copied from the event.
     * - Shipped_Date__c is set to today.
     * - Events for unknown order numbers are ignored.
     * - Cancelled orders are never changed.
     * - When multiple events refer to the same order, the last one in the list wins.
     *
     * @param events The platform event records to process.
     */
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Determine the winning event per order number (last one in the list wins).
        // Order numbers are matched case-insensitively against the upper-case external id.
        Map<String, FB_Shipment_Event__e> latestByOrder = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            latestByOrder.put(event.Order_Number__c.toUpperCase().trim(), event);
        }

        if (latestByOrder.isEmpty()) {
            return;
        }

        // Single SOQL query for all candidate orders.
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :latestByOrder.keySet()
        ];

        // Build the update set in memory, never touching Cancelled orders.
        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        Date shippedDate = Date.today();
        for (FB_Sales_Order__c order : orders) {
            if (order.Status__c == 'Cancelled') {
                continue;
            }
            FB_Shipment_Event__e event = latestByOrder.get(order.Order_Number__c.toUpperCase().trim());
            order.Status__c = 'Shipped';
            order.Tracking_Number__c = event.Tracking_Number__c;
            order.Carrier__c = event.Carrier__c;
            order.Shipped_Date__c = shippedDate;
            ordersToUpdate.add(order);
        }

        // Single DML statement.
        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
