     *         calendar year. Never contains null values.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> wonAmounts = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return wonAmounts;
        }

        // Seed every requested account with 0 so blanks map to 0, never null,
        // and so Ids with no qualifying opportunities remain present.
        for (Id accountId : accountIds) {
            wonAmounts.put(accountId, 0);
        }

        // Current calendar year bounds: Jan 1 through Dec 31 of the current year.
        Integer currentYear = Date.today().year();
        Date startDate = Date.newInstance(currentYear, 1, 1);
        Date endDate = Date.newInstance(currentYear, 12, 31);

        // Single aggregate query grouped by account; the individual opportunity
        // records are never loaded into Apex.
        for (AggregateResult ar : [
            SELECT AccountId,
                   SUM(Amount) totalWonAmount
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND CloseDate >= :startDate
              AND CloseDate <= :endDate
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalWonAmount');

            // Defensive guard: only override requested accounts and treat a null
            // sum (e.g. all qualifying opportunities have blank Amount) as 0.
            if (accountId != null && wonAmounts.containsKey(accountId)) {
                wonAmounts.put(accountId, total == null ? 0 : total);
            }
        }

        return wonAmounts;
    }
}
