    /*
     * ContactPhoneCleanup
     *
     * Utility that rewrites each Contact's Phone so it only contains digits and a
     * leading plus sign, which is the format the new dialer accepts. Every other
     * character (spaces, parentheses, dashes, letters, ...) is stripped out, e.g.
     * "+44 (20) 7946-0018" -> "+442079460018".
     */

    /**
     * Normalizes the Phone field of the supplied Contacts.
     *
     * @param contactIds Ids of the Contacts to process (expected up to 200 at a time).
     * @return A map of Contact Id to its first validation/save error for every
     *         Contact that could not be saved. Returns an empty map when every
     *         Contact was saved successfully (or when there was nothing to save).
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contacts) {
            // Contacts without a phone are left out.
            if (String.isBlank(contact.Phone)) {
                continue;
            }

            String normalizedPhone = contact.Phone.replaceAll('[^0-9+]', '');

            // Only touch records whose value actually changes.
            if (normalizedPhone != contact.Phone) {
                contact.Phone = normalizedPhone;
                contactsToUpdate.add(contact);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return failures;
        }

        // allOrNone = false so one bad record does not roll back the others.
        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Database.SaveResult saveResult : saveResults) {
            if (!saveResult.isSuccess()) {
                List<Database.Error> errors = saveResult.getErrors();
                if (errors != null && !errors.isEmpty()) {
                    failures.put(saveResult.getId(), errors[0].getMessage());
                }
            }
        }

        return failures;
    }
}
