public class ErpCustomerSync {

    private static final String ENDPOINT = 'callout:ERP/api/customers';

    /**
     * Pushes every new Account to the ERP as its own customer request.
     * One HTTP callout is issued per Account (iterating Trigger.new) so the
     * ERP team can trace each account individually, as requested.
     */
    public static void pushToErp(List<Account> accounts) {
        if (accounts == null) {
            return;
        }
        for (Account account : accounts) {
            sendCustomer(account);
        }
    }

    private static void sendCustomer(Account account) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(buildCustomerJson(account));
        request.setTimeout(120000);

        HttpResponse response = new Http().send(request);

        // The ERP answers 202 Accepted. Error handling and retries are
        // explicitly out of scope for this ticket, so nothing else to do.
        System.debug(LoggingLevel.INFO,
            'Pushed account ' + account.Id + ' to ERP, status ' + response.getStatusCode());
    }

    private static String buildCustomerJson(Account account) {
        Map<String, Object> customer = new Map<String, Object>();
        customer.put('salesforceId', String.valueOf(account.Id)); // 18-char Id
        customer.put('name', account.Name);
        customer.put('country', getCountry(account));             // null when blank

        List<Map<String, Object>> customers = new List<Map<String, Object>>();
        customers.add(customer);

        return JSON.serialize(customers);
    }

    private static String getCountry(Account account) {
        String country = account.BillingCountry;
        return String.isBlank(country) ? null : country;
    }
}
