```apex
public class AccountCountrySync {

    /**
     * Syncs BillingCountry -> MailingCountry for the contacts of accounts whose
     * BillingCountry changed in this transaction.
     *
     * @param updatedAccounts  Trigger.new   (List<Account>)     - new versions
     * @param previousAccounts Trigger.oldMap (Map<Id, Account>) - old versions by Id
     */
    public static void syncCountry(List<Account> updatedAccounts, Map<Id, Account> previousAccounts) {
        // 1) Determine which accounts actually changed BillingCountry.
        //    previousAccounts holds the previous value so we can compare.
        //    Only these accounts' contacts are ever touched.
        Map<Id, String> newCountryByAccount = new Map<Id, String>();
        for (Account acc : updatedAccounts) {
            Account previous = previousAccounts.get(acc.Id);
            String oldCountry = previous == null ? null : previous.BillingCountry;
            if (acc.BillingCountry != oldCountry) {
                newCountryByAccount.put(acc.Id, acc.BillingCountry);
            }
        }

        // Nothing changed on any account in this batch -> nothing to sync.
        if (newCountryByAccount.isEmpty()) {
            return;
        }

        // 2) Load the relevant contacts in ONE query, scoped to the changed accounts.
        //    Filtering by AccountId keeps the query heap-safe (we never pull the
        //    whole 2.3M-row Contact table) while staying a single query, no loops.
        //    Group results by AccountId manually (the Map(Id, List) constructor
        //    keys by Contact.Id, not AccountId).
        Map<Id, List<Contact>> contactsByAccount = new Map<Id, List<Contact>>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccount.keySet()
        ]) {
            List<Contact> list = contactsByAccount.get(c.AccountId);
            if (list == null) {
                list = new List<Contact>();
                contactsByAccount.put(c.AccountId, list);
            }
            list.add(c);
        }

        // 3) Pick the contacts that must follow the account: MailingCountry is blank
        //    OR equals the account's PREVIOUS BillingCountry. Only update when the
        //    value would actually change (skips no-ops).
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Id accId : newCountryByAccount.keySet()) {
            String newCountry = newCountryByAccount.get(accId);
            Account previous = previousAccounts.get(accId);
            String oldCountry = previous == null ? null : previous.BillingCountry;

            List<Contact> contacts = contactsByAccount.get(accId);
            if (contacts == null) {
                continue; // account has no contacts
            }

            for (Contact c : contacts) {
                String mailingCountry = c.MailingCountry;
                Boolean matchesRule = String.isBlank(mailingCountry)
                    || mailingCountry == oldCountry;

                if (matchesRule && mailingCountry != newCountry) {
                    c.MailingCountry = newCountry;
                    contactsToUpdate.add(c);
                }
            }
        }

        // 4) One bulk DML statement.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
