```js
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    results = [];
    error;

    // Handle of the pending debounce timer.
    _debounceTimer;
    // Monotonically increasing token; only the newest request may update results.
    _requestId = 0;

    /**
     * Fired on every keystroke. Reschedules a debounced call to Apex and
     * cancels any previously scheduled call.
     */
    handleChange(event) {
        this.searchTerm = event.target.value;

        // Cancel any previously scheduled (debounced) search.
        window.clearTimeout(this._debounceTimer);

        this._debounceTimer = window.setTimeout(() => {
            const trimmed = (this.searchTerm || '').trim();

            // Fewer than MIN_SEARCH_LENGTH characters: cancel any pending
            // (in-flight) search, do not call Apex and clear the results.
            if (trimmed.length < MIN_SEARCH_LENGTH) {
                this._requestId += 1;
                this.results = [];
                this.error = undefined;
                return;
            }

            this.search(trimmed);
        }, DEBOUNCE_MS);
    }

    /**
     * Imperatively calls Apex. Guards against out-of-order responses and
     * against updating results after the component has been removed.
     */
    search(trimmed) {
        this._requestId += 1;
        const currentRequestId = this._requestId;

        searchContacts({ searchTerm: trimmed })
            .then((data) => {
                // Ignore responses to older requests or to a removed component.
                if (currentRequestId !== this._requestId || !this.isConnected) {
                    return;
                }
                this.results = data ?? [];
                this.error = undefined;
            })
            .catch((error) => {
                // Ignore failures from older requests or a removed component.
                if (currentRequestId !== this._requestId || !this.isConnected) {
                    return;
                }
                this.results = [];
                this.error =
                    error?.body?.message ??
                    error?.message ??
                    'An unexpected error occurred';
            });
    }

    /**
     * Cancels the debounce timer when the component is removed so a pending
     * search never runs.
     */
    disconnectedCallback() {
        window.clearTimeout(this._debounceTimer);
    }
}
