```js
import { api, LightningElement } from 'lwc';
import FAVORITE_ADD from '@salesforce/label/c.Favorite_Add';
import FAVORITE_REMOVE from '@salesforce/label/c.Favorite_Remove';

/**
 * favoriteToggle
 *
 * Icon-style toggle button that marks a record as a favourite.
 * The parent owns the source-of-truth `favorite` value and passes it in via the
 * public property; it may change that value at any time (e.g. after a server
 * refresh) and the button reflects whatever it currently holds.
 *
 * A click optimistically flips the displayed state and emits a `favoritechange`
 * event whose detail is `{ favorite: <new boolean value> }`.
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favourite.
     * Set by the parent; reactive so external changes are shown immediately.
     *
     * Backed by a private field so the click handler can flip the state
     * locally without reassigning the public property (which the LWC lint
     * rules forbid).
     */
    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = Boolean(value);
    }

    /**
     * Internal source of truth.
     */
    _favorite = false;

    /**
     * aria-pressed is an enumerated attribute and must be the string
     * "true" / "false". Binding a bare boolean would drop the attribute
     * entirely when the value is false.
     */
    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    /**
     * Label describing the action a click performs:
     * the Remove label when it is a favourite, the Add label when it is not.
     * Reused for both aria-label and title.
     */
    get actionLabel() {
        return this._favorite ? FAVORITE_REMOVE : FAVORITE_ADD;
    }

    get buttonClass() {
        return this._favorite
            ? 'slds-button slds-button_icon'
            : 'slds-button slds-button_icon-border';
    }

    handleFavoriteClick() {
        const nextFavorite = !this._favorite;

        // Optimistic UI update: reflect the new state immediately.
