// function in a running org. Some Jest configurations mock the module with a
// default export that is not callable; guard against that so the component can
// still be imported (and its suite executed) in the test environment.
const MixinBase =
    typeof NavigationMixin === 'function'
        ? NavigationMixin(LightningElement)
        : LightningElement;

