public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and lets NPSP's own
     * trigger schedule the installment Opportunities (we never create them here).
     *
     * The new Recurring Donation Ids are returned in the same order as the input
     * requests. The whole batch uses at most one SOQL query and one DML statement.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // A null or empty list short-circuits to an empty result.
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();
        Set<Id> contactIds = new Set<Id>();

        // Validate every request up front so nothing is committed on error.
        for (GiftRequest req : requests) {
            if (req == null || req.contactId == null) {
                throw new RecurringGiftException(
                    'A donor Contact is required for every recurring gift.'
                );
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('A positive donation amount is required.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('The day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('A start date is required for every recurring gift.');
            }

            contactIds.add(req.contactId);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                npe03__Contact__c = req.contactId,
                npe03__Amount__c = req.amount,
                npe03__Installment_Period__c = 'Monthly',
                npsp__RecurringType__c = 'Monthly',
                npsp__InstallmentFrequency__c = 1,
                npsp__StartDate__c = req.startDate,
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = req.paymentMethod,
                npsp__Day_of_Month__c = req.dayOfMonth,
                // The form's "31" maps to ERD's own last-day-of-month option;
                // 29 and 30 (and 1-28) are stored as the literal day.
                npsp__Always_Use_Last_Day_Of_Month__c = req.dayOfMonth == 31
            );

            if (req.installments == null || req.installments <= 0) {
                // Open-ended recurring donation: no end date.
                rd.npe03__Open_Ended_Status__c = true;
            } else {
                // Fixed-length recurring donation with the given number of installments.
                rd.npe03__Open_Ended_Status__c = false;
                rd.npe03__Installments__c = req.installments;
            }

            recurringDonations.add(rd);
        }

        // Resolve each donor's Household/Organization account in a single query.
        Map<Id, Id> contactToOrganization = new Map<Id, Id>();
        for (Contact c : [SELECT Id, AccountId FROM Contact WHERE Id IN :contactIds]) {
            contactToOrganization.put(c.Id, c.AccountId);
        }
        for (Integer i = 0; i < recurringDonations.size(); i++) {
            recurringDonations[i].npe03__Organization__c =
                contactToOrganization.get(recurringDonations[i].npe03__Contact__c);
        }

        // One bulk insert. NPSP's Recurring Donation trigger generates the
        // installment Opportunities itself; this service creates none.
        insert recurringDonations;

        // Ids are populated in list (request) order.
        return recurringDonations.getIds();
    }
}
