public class SoftCreditService {

    /**
     * Thrown when a peer-to-peer soft credit request cannot be honored.
     * The whole call is validated before any DML, so a throw means nothing changed.
     */
    public class SoftCreditException extends Exception {}

    /**
     * A single peer-to-peer fundraising soft credit request.
     */
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Credits each fundraiser (contact) for `amount` of the gift on `opportunityId`,
     * using an NPSP Partial Soft Credit linked to the contact's OpportunityContactRole.
     *
     * Bulk-safe: a full call validates every request before any DML and stays within
     * 4 SOQL queries and 2 DML statements regardless of size.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }
        if (oppIds.isEmpty() || contactIds.isEmpty()) {
            return;
        }

        // --- SOQL 1: Opportunities (primary contact + amount for validation) ---
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, npsp__Primary_Contact__c, Amount
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // --- SOQL 2: Opportunity Contact Roles for these opp/contact pairs ---
        Map<String, List<OpportunityContactRole>> ocrsByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String k = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByKey.containsKey(k)) {
                ocrsByKey.put(k, new List<OpportunityContactRole>());
            }
            ocrsByKey.get(k).add(ocr);
        }

        // --- SOQL 3: Existing partial soft credits (to update instead of duplicate) ---
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            pscByKey.put(pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c), psc);
        }

        // --- SOQL 4: Contact names for the Contact_Name field ---
        Map<Id, String> contactNameById = new Map<Id, String>();
        for (Contact c : [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]) {
            contactNameById.put(c.Id, c.Name);
        }

        // --- Validate the entire call before any DML (all-or-nothing) ---
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            Decimal amount = req.amount;
            if (amount == null || amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be a positive number (opportunity ' + req.opportunityId + ').');
            }
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'A fundraiser cannot be credited on their own primary opportunity (contact ' + req.contactId + ').');
            }
            Decimal oppAmount = opp.Amount;
            if (oppAmount != null && amount > oppAmount) {
                throw new SoftCreditException(
                    'Soft credit amount ' + amount + ' exceeds opportunity amount ' + oppAmount + '.');
            }
        }

        // --- Build insert/update batches (no per-record DML) ---
        List<npsp__Partial_Soft_Credit__c> toInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> toUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            String k = pairKey(req.opportunityId, req.contactId);

            OpportunityContactRole ocr = pickOcr(ocrsByKey.get(k), req.role);
            String roleName = (req.role != null) ? req.role
                : (ocr != null ? ocr.Role : null);

            npsp__Partial_Soft_Credit__c psc = pscByKey.get(k);
            if (psc != null) {
                // Existing credit: update amount and role rather than duplicate.
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = roleName;
                psc.npsp__Contact_Role_ID__c = (ocr != null ? ocr.Id : null);
                psc.npsp__Contact_Name__c = contactNameById.get(req.contactId);
                toUpdate.add(psc);
            } else {
                toInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = roleName,
                    npsp__Contact_Role_ID__c = (ocr != null ? ocr.Id : null),
                    npsp__Contact_Name__c = contactNameById.get(req.contactId)
                ));
            }
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }

    private static String pairKey(Id oppId, Id contactId) {
        return oppId + '|' + contactId;
    }

    /**
     * Returns the OpportunityContactRole for a pair whose Role matches the requested
     * role. With a single role (the expected case) it returns that one; when several
     * exist (e.g. NPSP's auto-added Household Member) it prefers the requested role.
     */
    private static OpportunityContactRole pickOcr(List<OpportunityContactRole> ocrs, String role) {
        if (ocrs == null || ocrs.isEmpty()) {
            return null;
        }
        if (role == null || ocrs.size() == 1) {
            return ocrs[0];
        }
        for (OpportunityContactRole ocr : ocrs) {
            if (role.equals(ocr.Role)) {
                return ocr;
            }
        }
        return ocrs[0];
    }
}
