public with sharing class PaymentPlanService {

    /**
     * Raised when a payment plan cannot be scheduled. No data is changed when
     * this exception is thrown.
     */
    public class PaymentPlanException extends Exception {}

    /**
     * Converts an open donation (pledge) into a monthly installment plan.
     *
     * History payments (paid or written-off) are preserved untouched. Every other
     * payment on the opportunity (unpaid and not written-off) is deleted and
     * replaced with numberOfPayments new unpaid payments, scheduled one month
     * apart starting on firstPaymentDate (payment i is scheduled on
     * firstPaymentDate.addMonths(i)).
     *
     * The outstanding amount (Opportunity Amount minus the amounts of paid and
     * written-off payments) is split evenly across the new payments, rounded down
     * to the cent. The last payment absorbs the rounding remainder so the new
     * payments sum exactly to the outstanding amount.
     *
     * @param opportunityId   Id of the opportunity to schedule payments for
     * @param numberOfPayments number of installments to create (must be >= 1)
     * @param firstPaymentDate date of the first installment; subsequent ones are monthly
     * @return                the newly created payments, in schedule order
     * @throws PaymentPlanException if numberOfPayments is null or less than 1, the
     *         opportunity is closed, or the outstanding amount is not greater than
     *         zero. No data is changed when this is thrown.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
            Id opportunityId,
            Integer numberOfPayments,
            Date firstPaymentDate) {

        // --- Validation: all checks run before any DML so failures change nothing ---

        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be a positive integer.');
        }

        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule a payment plan on a closed opportunity.');
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // Outstanding = Opportunity Amount minus history (paid / written-off) payments.
        Decimal outstanding = opp.Amount != null ? opp.Amount : 0;
        for (npe01__OppPayment__c pm : existingPayments) {
            if (pm.npe01__Paid__c || pm.npe01__Written_Off__c) {
                outstanding -= pm.npe01__Payment_Amount__c != null
                    ? pm.npe01__Payment_Amount__c : 0;
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'There is no outstanding (unpaid) amount to schedule.');
        }

        // --- Build the installment plan ---

        // Even share, rounded down to the cent.
        Decimal perPayment = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> newPayments =
            new List<npe01__OppPayment__c>(numberOfPayments);

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount = (i == numberOfPayments - 1)
                // Last payment absorbs the rounding remainder.
                ? (outstanding - (perPayment * (numberOfPayments - 1)))
                    .setScale(2, RoundingMode.DOWN)
                : perPayment;

            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false
            ));
        }

        // --- Persist: remove the old open payments, then add the plan ---

        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c pm : existingPayments) {
            if (!pm.npe01__Paid__c && !pm.npe01__Written_Off__c) {
                paymentsToDelete.add(pm);
            }
        }

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        insert newPayments;

        return newPayments;
    }
}
