public class GiftService {

    /**
     * Records a gift (a Closed Won donation) that has already been received.
     *
     * The gift is credited using NPSP conventions:
     * <ul>
     *   <li>the Opportunity lives on the contact's Household Account;</li>
     *   <li>the contact is the Opportunity's primary contact (npsp__Primary_Contact__c)
     *       and holds the "Donor" Opportunity Contact Role (flagged as primary);</li>
     *   <li>every other member of the household holds the "Household Member"
     *       Opportunity Contact Role;</li>
     *   <li>the Opportunity has exactly one payment, for the full amount, marked
     *       as paid, dated on {@code giftDate}.</li>
     * </ul>
     *
     * @param contactId Id of the donor contact
     * @param amount    positive amount of the gift
     * @param giftDate  date the gift was received (used as the Opportunity close
     *                  date and the payment date)
     * @return          the Id of the created Opportunity
     * @throws IllegalArgumentException if the contact does not exist, or if
     *                                  {@code amount} is null, zero or negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // --- Validate the amount --------------------------------------------
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be a positive number.');
        }

        // --- Validate the contact exists ------------------------------------
        // Query a List so that "no rows" does not raise a QueryException; instead
        // we throw the required IllegalArgumentException.
        List<Contact> found = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
        ];
        if (found.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact contact = found[0];

        // --- Resolve the household ------------------------------------------
        // In the NPSP Household Account model every member of a household shares
        // the donor contact's AccountId.
        List<Contact> householdMembers = [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :contact.AccountId
        ];

        // --- Build the Opportunity name -------------------------------------
        // <FirstName> <LastName> Donation <yyyy-MM-dd>, e.g. "Jane Smith Donation 2026-03-01".
        String firstName = String.isNotBlank(contact.FirstName) ? contact.FirstName.trim() : '';
        String lastName = String.isNotBlank(contact.LastName) ? contact.LastName.trim() : '';
        Integer y = giftDate.year();
        Integer m = giftDate.month();
        Integer d = giftDate.day();
        String dateLabel = y + '-' + ((m < 10 ? '0' : '') + m) + '-' + ((d < 10 ? '0' : '') + d);
        String oppName = (firstName + ' ' + lastName).trim() + ' Donation ' + dateLabel;

        // --- Create the Closed Won donation Opportunity ----------------------
        Opportunity opp = new Opportunity(
            Name = oppName,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            AccountId = contact.AccountId,
            npsp__Primary_Contact__c = contact.Id
        );
        insert opp;

        // --- Opportunity Contact Roles --------------------------------------
        // NPSP may add a contact role automatically when npsp__Primary_Contact__c
        // is set, so we start from whatever already exists and make sure no
        // contact ever ends up with more than one role on this Opportunity.
        Map<Id, OpportunityContactRole> existingRoles = new Map<Id, OpportunityContactRole>(
            [SELECT Id, ContactId, Role, IsPrimary
             FROM OpportunityContactRole
             WHERE OpportunityId = :opp.Id]
        );

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        // Primary contact -> "Donor" role, flagged as primary.
        OpportunityContactRole existingPrimary = existingRoles.get(contact.Id);
        if (existingPrimary == null) {
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = contact.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
        } else {
            existingPrimary.Role = 'Donor';
            existingPrimary.IsPrimary = true;
            rolesToUpdate.add(existingPrimary);
        }

        // Every other household member -> "Household Member" role.
        for (Contact member : householdMembers) {
            if (member.Id == contact.Id) {
                continue; // primary contact handled above
            }
            OpportunityContactRole existing = existingRoles.get(member.Id);
            if (existing == null) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId = member.Id,
                    Role = 'Household Member'
                ));
            } else if (existing.Role != 'Household Member') {
                existing.Role = 'Household Member';
                rolesToUpdate.add(existing);
            }
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }

        // --- Single paid payment for the full amount -------------------------
        // The Opportunity was just created, so it has no existing payments; this
        // guarantees exactly one, with no duplicates.
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }
}
