public with sharing class RecordAccessService {

    /**
     * Maximum number of record IDs checked per SOQL query against UserRecordAccess.
     * 2,000 IDs / 100 per query = 20 queries, staying within the SOQL budget even when
     * the method shares a transaction with other logic.
     */
    private static final Integer BATCH_SIZE = 100;

    /**
     * Returns the subset of {@code recordIds} that the running user can edit.
     *
     * <p>Edit access is determined by the {@code UserRecordAccess} object
     * ({@code HasEditAccess}). That value already reflects object-level permissions,
     * record ownership, sharing rules, the role hierarchy and the user's View All /
     * Modify All privileges, so no additional checks are needed here.</p>
     *
