/*
 * ContactImportService
 *
 * Bulk-safe helper for migrating Contact records from the legacy system. Only the TAF
 * after-insert welcome-pack Task action (TA_Contact_CreateWelcomeTask) is bypassed for
 * the duration of the import DML; every other Contact automation (including the
 * before-insert phone formatter) still executes. The bypass is cleared in a finally
 * block so it never leaks into subsequent DML in the same transaction.
 */
public with sharing class ContactImportService {
    /**
     * Inserts the supplied Contacts in a single DML statement, skipping only the
     * TA_Contact_CreateWelcomeTask action. The bypass is scoped to this DML only and
     * is always cleared afterwards.
     *
     * @param contacts Contacts to import; may be null or empty.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Action-level bypass: skip only the welcome-task action, leaving all other
        // Contact automation (e.g. the before-insert phone formatter) intact.
        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');
        try {
            insert contacts;
        } finally {
            // Restore default behaviour so later inserts in this transaction run the
            // welcome-task action as usual, regardless of whether the insert succeeded.
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
