 * TA_Contact_PreventDuplicateEmail
 *
 * Trigger action (Trigger Actions Framework 0.3.4) enforcing that two contacts on the same
 * account may not share an email address (compared case-insensitively).
 *
 * Contexts: before insert and before update.
 *  - Contacts without an Account or without an Email are never checked.
 *  - On update, only contacts whose Email or AccountId changed are checked, and a contact
 *    never conflicts with itself.
 *  - Within one save the first contact to claim an (account, email) pair wins; every later
 *    one gets a record-level error, so partial saves keep the valid rows.
 *  - At most one SOQL query is issued per trigger execution, for up to 200 records.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_MESSAGE =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforceNoDuplicateEmails(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforceNoDuplicateEmails(triggerNew, triggerOld);
    }

    private void enforceNoDuplicateEmails(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // Only contacts that have an account are subject to the rule; contacts with no email
        // are filtered out again below.
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew[i];
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // The single SOQL query for this execution. We load every contact on the relevant
        // accounts and do the case-insensitive comparison in Apex (SOQL cannot lower-case a
        // field inside a WHERE clause), keeping ids so a record can be told apart from itself.
        Map<String, Set<Id>> keyToContactIds = new Map<String, Set<Id>>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            if (c.Email == null) {
                continue;
            }
            String key = buildKey(c.AccountId, c.Email);
            if (!keyToContactIds.containsKey(key)) {
                keyToContactIds.put(key, new Set<Id>());
            }
            keyToContactIds.get(key).add(c.Id);
        }

        // Walk the batch in order: the first contact to claim a key wins, later ones fail.
        Set<String> seenKeys = new Set<String>();
        Integer size = triggerNew.size();
        for (Integer i = 0; i < size; i++) {
            Contact newC = (Contact) triggerNew[i];
            if (newC.AccountId == null || newC.Email == null) {
                continue;
            }

            // On update, skip contacts whose account and email are both unchanged, and only
            // compare against other records (a contact never conflicts with itself).
            if (triggerOld != null && triggerOld[i] != null) {
                Contact oldC = (Contact) triggerOld[i];
                if (!isAccountOrEmailChanged(newC, oldC)) {
                    continue;
                }
            }

            String key = buildKey(newC.AccountId, newC.Email);
            Boolean alreadyExists = hasOtherContact(newC.Id, key, keyToContactIds);
            Boolean seenInBatch = seenKeys.contains(key);

            if (alreadyExists || seenInBatch) {
                newC.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                seenKeys.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + '|' + email.toLowerCase();
    }

    private static Boolean hasOtherContact(Id selfId, String key,
            Map<String, Set<Id>> keyToContactIds) {
        Set<Id> ids = keyToContactIds.get(key);
        if (ids == null) {
            return false;
        }
        for (Id existingId : ids) {
            if (existingId != selfId) {
                return true;
            }
        }
        return false;
    }

    private static Boolean isAccountOrEmailChanged(Contact newC, Contact oldC) {
        Boolean emailChanged = oldC.Email == null
                ? true
                : !newC.Email.equalsIgnoreCase(oldC.Email);
        return emailChanged || newC.AccountId != oldC.AccountId;
    }
}
