trigger OpportunityTrigger on Opportunity (
    before insert,
    before update,
    before delete,
    after insert,
    after update,
    after delete,
    after undelete
) {
    MetadataTriggerHandler handler = new MetadataTriggerHandler();

    if (Trigger.isBeforeInsert) {
        handler.beforeInsert(Trigger.new);
    } else if (Trigger.isBeforeUpdate) {
        handler.beforeUpdate(Trigger.new, Trigger.old);
    } else if (Trigger.isBeforeDelete) {
        handler.beforeDelete(Trigger.old);
    } else if (Trigger.isAfterInsert) {
        handler.afterInsert(Trigger.new);
    } else if (Trigger.isAfterUpdate) {
        handler.afterUpdate(Trigger.new, Trigger.old);
    } else if (Trigger.isAfterDelete) {
        handler.afterDelete(Trigger.old);
    } else if (Trigger.isAfterUndelete) {
        handler.afterUndelete(Trigger.new);
    }
}
