public without sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert,
                   TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete,
                   TriggerAction.AfterUndelete {

    /*
     * Keeps Account.FB_Open_Case_Count__c equal to the number of open
     * (IsClosed = false) Cases that look up to the Account.
     *
     * Each context works out the per-Account change (delta) produced by the
     * operation and applies it to the stored value. Only Accounts whose count
     * actually changes are updated, so a whole trigger execution costs at most
     * one SOQL query and one DML statement, is safe for 200-row batches, and
     * never leaves the field blank (a count that reaches zero is written as 0).
     *
     * Runs without sharing so record-level Account sharing rules never block the
     * count from being maintained, whatever user or integration changes the Case.
     * The action only touches Account, so it can never re-enter the Case trigger.
     */

    public void afterInsert(List<SObject> triggerNew) {
        Map<Id, Integer> deltas = new Map<Id, Integer>();
        for (SObject rec : triggerNew) {
            Case c = (Case) rec;
            if (c.AccountId != null && isOpen(c)) {
                addDelta(deltas, c.AccountId, 1);
            }
        }
        apply(deltas);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Integer> deltas = new Map<Id, Integer>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case nw = (Case) triggerNew[i];
            Case old = (Case) triggerOld[i];
            Boolean oldOpen = isOpen(old);
            Boolean newOpen = isOpen(nw);
            if (nw.AccountId == old.AccountId) {
                // Same Account: only the open/closed transition matters.
                if (oldOpen && !newOpen) {
                    addDelta(deltas, nw.AccountId, -1);
                } else if (!oldOpen && newOpen) {
                    addDelta(deltas, nw.AccountId, 1);
                }
            } else {
                // Account changed: the old one loses an open Case, the new one gains one.
                addDelta(deltas, old.AccountId, oldOpen ? -1 : 0);
                addDelta(deltas, nw.AccountId, newOpen ? 1 : 0);
            }
        }
        apply(deltas);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Map<Id, Integer> deltas = new Map<Id, Integer>();
        for (SObject rec : triggerOld) {
            Case c = (Case) rec;
            if (c.AccountId != null && isOpen(c)) {
                addDelta(deltas, c.AccountId, -1);
            }
        }
        apply(deltas);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Map<Id, Integer> deltas = new Map<Id, Integer>();
        for (SObject rec : triggerNew) {
            Case c = (Case) rec;
            if (c.AccountId != null && isOpen(c)) {
                addDelta(deltas, c.AccountId, 1);
            }
        }
        apply(deltas);
    }

    // A Case counts as open unless IsClosed is explicitly true.
    private static Boolean isOpen(Case c) {
        return c.IsClosed == null || !c.IsClosed;
    }

    private static void addDelta(Map<Id, Integer> deltas, Id accountId, Integer delta) {
        if (accountId == null || delta == 0) {
            return;
        }
        Integer current = deltas.get(accountId);
        deltas.put(accountId, (current == null ? 0 : current) + delta);
    }

    private void apply(Map<Id, Integer> deltas) {
        if (deltas.isEmpty()) {
            return;
        }
        List<Account> toUpdate = new List<Account>();
        for (Account a : [SELECT Id, FB_Open_Case_Count__c FROM Account WHERE Id IN :deltas.keySet()]) {
            Integer next = (a.FB_Open_Case_Count__c == null ? 0 : a.FB_Open_Case_Count__c) + deltas.get(a.Id);
            if (next < 0) {
                next = 0;
            }
            a.FB_Open_Case_Count__c = next;
            toUpdate.add(a);
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
