public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    // Tracks the Opportunities we've already audited in the current transaction.
    // Static state survives recursive trigger fires within the same transaction, so
    // when the rounding action updates the Opportunities again, this guard prevents a
    // second "Amount changed" Task for the same record. It is reset between transactions,
    // so a later genuine Amount change is still logged.
    private static Set<Id> oppsLoggedInTransaction = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Skip records with no Id, records whose Amount did not change, and records
            // we've already audited in this transaction (rounding re-update guard).
            if (newOpp.Id == null
                    || oldOpp.Amount == newOpp.Amount
                    || oppsLoggedInTransaction.contains(newOpp.Id)) {
                continue;
            }

            oppsLoggedInTransaction.add(newOpp.Id);
            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = newOpp.Id,
                Status = 'Completed'
            ));
        }

        // Single bulk-safe DML per trigger execution.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
